import { labels } from "../data/member-options.js";
export const escapeHtml=value=>String(value??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#039;",'"':"&quot;"}[c]));
export const label=value=>labels[value]||escapeHtml(value||"");
export const formatDate=value=>value?new Intl.DateTimeFormat("en-PH",{year:"numeric",month:"long",day:"numeric"}).format(new Date(`${value}T00:00:00`)):"Date unavailable";
export const pageHeader=(eyebrow,title,description,action="")=>`<header class="page-header"><div><p class="eyebrow">${escapeHtml(eyebrow)}</p><h1 tabindex="-1">${escapeHtml(title)}</h1><p>${escapeHtml(description)}</p></div>${action}</header>`;
export const notice=(text,type="info",title="Educational-use notice")=>`<aside class="notice notice-${type}" role="note"><span aria-hidden="true">${type==="warning"?"!":"i"}</span><div><strong>${escapeHtml(title)}</strong><p>${escapeHtml(text)}</p></div></aside>`;
export const professionalNotice=()=>notice("Use these results as a discussion guide. A qualified fitness professional can help you decide which exercise or nutrition strategies are appropriate for you.","warning","Discuss your results with a professional");
export function toast(message){const region=document.querySelector("#toast-region");if(!region)return;region.innerHTML=`<div class="toast">${escapeHtml(message)}</div>`;setTimeout(()=>region.innerHTML="",3200)}
export function modal({title,body,confirmText="Continue",cancelText="Close",danger=false,onConfirm}){const root=document.querySelector("#modal-root");root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${escapeHtml(title)}</h2><button class="icon-button" data-close-modal aria-label="Close">×</button></div><div class="modal-body">${body}</div><div class="button-row"><button class="button ${danger?"button-danger":"button-primary"}" data-confirm-modal>${escapeHtml(confirmText)}</button><button class="button button-secondary" data-close-modal>${escapeHtml(cancelText)}</button></div></section></div>`;const close=()=>root.innerHTML="";root.querySelectorAll("[data-close-modal]").forEach(button=>button.addEventListener("click",close));root.querySelector("[data-confirm-modal]").addEventListener("click",()=>{onConfirm?.();close()});root.querySelector("[data-close-modal]").focus()}
export const emptyState=(title,text,href,labelText)=>`<section class="card empty-state"><span class="empty-icon" aria-hidden="true">○</span><h1 tabindex="-1">${escapeHtml(title)}</h1><p>${escapeHtml(text)}</p>${href?`<a class="button button-primary" href="${href}">${escapeHtml(labelText)}</a>`:""}</section>`;
